"summary": "Renderer container in reports Deployment is throttled at its CPU limit, causing liveness probe failures. Increase CPU limit to 1.5 cores.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Current CPU limit of 1 core is insufficient for renderer container's 0.93 usage and 41% throttling.",
    "supporting": ["ev-container_cpu", "ev-revision_health"],
