],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise renderer's CPU limit from 1 core to 1.5 cores to clear throttling and prevent liveness probe failures.",
  "rationale": "Current renderer uses 0.93 CPU (93% of 1 core limit) with 41% throttling, causing liveness probe timeouts. Increasing the limit to 1.5 cores would provide sufficient CPU capacity to avoid throttling and ensure proper operation.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-revision_health", "ev-pod_states", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
